import 'dart:convert';
import 'dart:io';
import '../lib/components/piano_keyboard_spec.dart';

void main(List<String> args) {
  final output =
      '// Generated by tools/sync_piano_keyboard.dart; edit PianoKeyboardSpec.\n'
      'globalThis.SornazPianoStyle=Object.freeze(${jsonEncode(PianoKeyboardSpec.browser)});\n';
  final paths = args.where((a) => a != '--check');
  for (final name
      in paths.isEmpty ? ['assets/notation/piano_style.js'] : paths) {
    final file = File(name);
    if (args.contains('--check')) {
      if (!file.existsSync() || file.readAsStringSync() != output)
        throw StateError('Outdated piano style: $name');
    } else {
      file.writeAsStringSync(output);
    }
  }
}
